function currentPowerRows(){const p=E.powerMetrics?E.powerMetrics():[];const by=Object.fromEntries((Y.teams||[]).map(t=>[t.team,t]));return p.length?p.map(x=>({...by[x.team],...x})):Y.teams||[]}
function ranks(){return currentPowerRows().map((t,i)=>`<a class="rank-card" href="franchise.html?manager=${encodeURIComponent(t.manager)}"><div class="rank-num">${t.powerRank||i+1}</div><div class="rank-team"><strong>${e(t.team)}</strong><small>${e(t.manager)} · ${t.gp?`${t.w}-${t.l}`:e(t.projection||'Preseason')}</small></div><div class="rank-grade"><strong>${e(t.grade||'—')}</strong><small>${t.powerIndex?`Power ${t.powerIndex.toFixed(1)}`:`Yahoo ${e(t.yahoo||'—')}`}</small></div></a>`).join('')}
const HOME_DRAFT_BOARD=[{"rank":1,"team":"Wheat Hill Slow Blows","manager":"Tommy","grade":"A+","yahoo":"B"},{"rank":2,"team":"SVDBaller","manager":"Harry","grade":"A+","yahoo":"A+"},{"rank":3,"team":"Rise of the Pleasure Machines","manager":"Christopher","grade":"A","yahoo":"C+"},{"rank":4,"team":"SFPAL Junior 49ers","manager":"Tom","grade":"A-","yahoo":"A+"},{"rank":5,"team":"Bogota Booger Boys","manager":"Andrew","grade":"B+","yahoo":"B-"},{"rank":6,"team":"The Great Communicator","manager":"Matt F.","grade":"A-","yahoo":"D"},{"rank":7,"team":"Premature Ejleculators","manager":"Matty B.","grade":"A-","yahoo":"B-"},{"rank":8,"team":"Jelq Me Jeantly","manager":"Owen","grade":"B+","yahoo":"D"},{"rank":9,"team":"The Breeder","manager":"Patrick","grade":"B","yahoo":"D"},{"rank":10,"team":"MCFISH","manager":"Danny","grade":"B","yahoo":"D+"}];

