function publishedWeeks(){return Object.entries(Y.weekly||{}).map(([w,d])=>({week:Number(w),...d})).filter(d=>d.writeup&&!/write-up pending/i.test(d.headline||'')&&!/bracket TBD/i.test(d.headline||'')).sort((a,b)=>b.week-a.week)}
function homepageWeeklies(){let p=publishedWeeks();if(!p.length)return '';let latest=p[0],older=p.slice(1,4);let old=older.length?`<div class="home-weekly-recent"><p class="eyebrow dark">RECENT WEEKS</p><div class="home-weekly-recent-grid">${older.map(d=>`<a class="home-weekly-mini" href="week.html?week=${d.week}"><small>WEEK ${d.week}</small><strong>${e(d.headline)}</strong><span>Read the write-up →</span></a>`).join('')}</div></div>`:'';return `<section class="section home-weekly-section"><div class="shell"><div class="section-head"><div><p class="eyebrow dark">FROM THE LEAGUE DESK</p><h2>Latest Weekly Write-Up</h2></div></div><article class="home-weekly-feature"><div class="home-weekly-copy"><div class="home-weekly-meta"><span>WEEK ${latest.week}</span><span>${e((latest.status||'write-up').toUpperCase())}</span></div><h3>${e(latest.headline)}</h3><p>${e(latest.preview||latest.writeup)}</p><div class="home-weekly-actions"><a class="button primary" href="weeks.html#latest-writeup">Read full Week ${latest.week} write-up</a><a class="home-archive-link" href="weeks.html#archive">All weekly write-ups →</a></div></div><aside class="home-weekly-side"><p class="eyebrow">GAME OF THE WEEK</p><h4>${e(latest.gameOfWeek||'To be earned')}</h4><p>${e(latest.gotwCopy||'')}</p><div class="home-weekly-side-rule"></div><p class="eyebrow">TOILET WATCH</p><p>${e(latest.toiletWatch||'Pending.')}</p></aside></article>${old}</div></section>`}
function liveBoardSection(week=CURRENT_WEEK){return `<section class="section scoreboard-section"><div class="shell"><div class="scoreboard-banner"><div><p class="eyebrow dark">LIVE SCOREBOARD</p><h2>Week ${week}</h2></div><p>Game states, projections, close-game alerts and upset watch.</p></div>${E.renderScoreboard?E.renderScoreboard(week):''}</div></section>`}
function home(){let h=(D.history||[]).map(x=>card(`${x.year} — ${x.champion}`,`<b>Runner-up:</b> ${e(x.runnerUp)}<br><b>Toilet:</b> ${e(x.toilet)}<br><br>${e(x.headline)}`)).join('');let leader=HOME_DRAFT_BOARD[0],weeklyHref='weeks.html#latest-writeup';return `<section class="hero"><div class="shell"><p class="eyebrow">2026 SEASON HUB</p><h1>Miscellaneous<br><em style="color:var(--lime);font-weight:400">Expenditures</em></h1><p class="lede">Three completed seasons of bad beats, keeper theft and playoff heartbreak — plus a 2026 title race built to add another chapter.</p><div class="hero-actions"><a class="button primary" href="draft-history.html#grades">Our 2026 Draft Verdict</a><a class="button ghost" href="${weeklyHref}">Weekly Write-Ups</a><a class="button ghost" href="season-2026.html">2026 War Room</a></div></div></section>`+liveBoardSection(1)+sec('The story so far',`<div class="grid3">${h}</div>`,'Records are nice. The real history is who won, who collapsed and who had to sit behind a microphone.','THREE YEARS OF POOR DECISIONS')+homepageWeeklies()+`<section class="section alt preseason-board"><div class="shell"><div class="section-head"><div><p class="eyebrow dark">OUR PRESEASON BOARD</p><h2>Not Yahoo's rankings</h2></div><p class="section-intro">We graded roster construction, keeper value, positional balance, depth and the price paid.</p></div><div class="notice red"><b>Draft winner: ${e(leader.manager)} — ${e(leader.team)} (${e(leader.grade)}).</b> Yahoo gave this roster ${e(leader.yahoo)}. We did not.</div>${draftRankCards()}</div></section>`}
function franchises(){
  const st=Object.fromEntries((E.currentStandings?E.currentStandings():[]).map(x=>[x.manager,x]));
  const h=(Y.teams||[]).map(t=>{
    const a=arch(t.manager),r=rec(t.manager),srow=st[t.manager],pre=HOME_DRAFT_BOARD.find(x=>x.manager===t.manager);
    const era=t.manager==='Tom'?'2025–PRESENT':'2023–PRESENT';
    const pct=r?.winPct?`${(Number(r.winPct)*100).toFixed(1)}%`:'—';
    return `<a class="card franchise franchise-ledger-card" href="franchise.html?manager=${encodeURIComponent(t.manager)}">
      <p class="eyebrow dark">${e(t.manager)} · ${era}</p>
      <h3>${e(t.team)}</h3>
      <div class="stat">${e(r?.record||'—')}</div>
      <div class="franchise-meta-line">${e(pct)} win rate · ${e(r?.titles??0)} titles · best ${e(r?.best||'—')}</div>
      <p class="franchise-blurb"><b>${e(a?.title||'')}</b><br>${e(a?.body||'')}</p>
      ${pre?`<p class="franchise-draft-line"><b>2026:</b> Our ${e(pre.grade)} · draft rank #${pre.rank}</p>`:''}
      ${srow?.gp?`<p class="small"><b>Right now:</b> ${srow.w}-${srow.l} · ${srow.pf.toFixed(2)} PF</p>`:''}
    </a>`;
  }).join('');
  return hero('Franchise Files','Every current franchise, from rings to Toilets.')+
    `<section class="section franchise-ledger-section"><div class="shell"><div class="section-head"><div><p class="eyebrow dark">THE FRANCHISE LEDGER</p><h2>Know your enemy</h2></div></div><div class="grid2 franchise-ledger-grid">${h}</div></div></section>`;
}
function franchise(){
  const m=Q.get('manager')||'Tommy',t=team(m),a=arch(m),r=rec(m);
  if(!t)return hero('Franchise not found');
  const st=(E.currentStandings?E.currentStandings():[]).find(x=>x.manager===m);
  const pow=(E.powerMetrics?E.powerMetrics():[]).find(x=>x.manager===m);
  const sim=(E.simulate?E.simulate():[]).find(x=>x.manager===m);
  const str=(E.streaks?E.streaks():{})[m]||'—';
  const sos=pow&&E.remainingSOS?E.remainingSOS(pow.team):null;
  const pre=HOME_DRAFT_BOARD.find(x=>x.manager===m);
  const live=pow&&sim?`<section class="section alt franchise-command-section"><div class="shell"><div class="section-head"><div><p class="eyebrow dark">RIGHT NOW</p><h2>2026 Command Center</h2></div><p class="section-intro">Standings, live power, postseason odds and the road still in front of this franchise.</p></div><div class="grid4 franchise-command-grid">${card('Current record',`${pow.gp?`${pow.w}-${pow.l}`:'0-0'}<br><span class="small">Seed #${pow.seed||'—'} · ${e(str)}</span>`,'STANDINGS')}${card('Live power',`#${pow.powerRank||'—'} · ${Number(pow.powerIndex||0).toFixed(1)}`,'POWER INDEX')}${card('Playoff picture',`${sim.playoff}% playoffs<br><span class="small">${sim.bye}% bye · ${sim.title}% title · ${sim.press}% press risk</span>`,'ODDS')}${card('Remaining road',`${sos==null?'—':sos.toFixed(2)} avg opp rank<br><span class="small">Seed range ${sim.seedLow}–${sim.seedHigh}</span>`,'SCHEDULE')}</div></div></section>`:'';
  const base=`<section class="section"><div class="shell profile-top"><div class="profile-box"><div class="big-record">${e(r?.record||'—')}</div><p class="franchise-profile-meta">${r?.winPct?`${(Number(r.winPct)*100).toFixed(1)}% career win rate · `:''}${e(r?.pf||'—')} PF · ${e(r?.titles??0)} titles · best ${e(r?.best||'—')}</p><p>${e(a?.body||'')}</p><div class="mini-stats"><div class="mini-stat"><b>${e(r?.pf||'—')}</b><small>Career PF</small></div><div class="mini-stat"><b>${st?.gp?`${st.w}-${st.l}`:e(t.projection)}</b><small>2026 record</small></div><div class="mini-stat"><b>${e(str)}</b><small>Current streak</small></div></div></div><div class="callout"><p class="eyebrow">FRANCHISE FILE</p><h3>${e(a?.title||t.team)}</h3><p>${e(t.outlook)}</p>${sim?`<p><b>${sim.playoff}% playoffs · ${sim.bye}% bye · ${sim.title}% title · ${sim.press}% press risk</b></p>`:''}</div></div></section>`;
  const outlook=sec('2026 outlook',`<div class="grid2">${card('The good',e(t.best),'WHY IT WORKS')}${card('How this goes wrong',e(t.concern),'THE RISK')}</div>`,'','OUR SCOUTING REPORT');
  const draft=pre?sec('Draft snapshot',`<div class="grid3">${card('Our grade',`<span class="grade-pill">${e(pre.grade)}</span>`,'ME VERDICT')}${card('Yahoo grade',`<span class="grade-pill yahoo-grade">${e(pre.yahoo)}</span>`,'YAHOO')}${card('Best value',e(DRAFT_BEST_VALUE[m]||'—'),'DRAFT DAY')}</div>`,'The draft-night grade stays frozen even when the live power index moves.','THE RECEIPTS'):'';
  const liveRoster=(Y.liveRosters||[]).find(x=>x.manager===m||x.team===t.team);
  const roster=liveRoster&&liveRoster.players?.length?sec('Current Yahoo roster',`<div class="table-wrap franchise-roster-wrap" tabindex="0"><table class="franchise-roster-table"><thead><tr><th>Slot</th><th>Player</th><th>NFL</th><th>Pos</th><th>Status</th></tr></thead><tbody>${liveRoster.players.map(p=>`<tr><td><b>${e(p.slot||'—')}</b></td><td><b>${e(p.name||'')}</b></td><td>${e(p.nflTeam||'')}</td><td>${e(p.pos||p.position||'')}</td><td>${e(p.status||'—')}</td></tr>`).join('')}</tbody></table></div>`,`Yahoo roster snapshot · ${e(liveRoster.capturedAt||Y.lastUpdated||'')}`,'LIVE ROSTER'):'';
  return hero(`${m} — ${t.team}`,a?.title||'')+live+base+outlook+draft+roster;
}
function archiveGames(){return E.allGames?E.allGames():[]}
function scoredGame(g){return Number.isFinite(g?.scoreA)&&Number.isFinite(g?.scoreB)}
function gameOrder(g){let r=String(g.round||'');let post=r==='Quarterfinal'?15:r==='Semifinal'||r==='Consolation Semifinal'?16:r==='Final'||/Place|Toilet/i.test(r)?17:0;return (Number(g.year)||0)*100+(Number(g.week)||post||0)}
function seriesDetail(a,b){
  const ms=archiveGames().filter(g=>((g.managerA===a&&g.managerB===b)||(g.managerA===b&&g.managerB===a))&&scoredGame(g)).sort((x,y)=>gameOrder(x)-gameOrder(y));
  let wa=0,wb=0;for(const g of ms){if(g.winner===a)wa++;else if(g.winner===b)wb++}
  let streak='—';if(ms.length){const last=ms[ms.length-1].winner;let n=0;for(let i=ms.length-1;i>=0&&ms[i].winner===last;i--)n++;streak=`${last} W${n}`}
  const largest=ms.length?[...ms].sort((x,y)=>Math.abs(y.scoreA-y.scoreB)-Math.abs(x.scoreA-x.scoreB))[0]:null,last=ms.at(-1)||null;
  return {meetings:ms.length,wa,wb,streak,last,largest};
}
function archiveManagers(){return [...new Set([...(Y.teams||[]).map(t=>t.manager),...archiveGames().flatMap(g=>[g.managerA,g.managerB])].filter(Boolean))]}
function archiveCareerRows(){
  const rows={};for(const m of archiveManagers())rows[m]={manager:m,seasons:new Set(),w:0,l:0,pf:0,pa:0,postW:0,postL:0,titles:0,finals:0,toilets:0,best:99};
  for(const g of archiveGames()){if(!scoredGame(g))continue;for(const m of [g.managerA,g.managerB]){if(!rows[m])continue;rows[m].seasons.add(g.year);const won=g.winner===m,pts=won?g.scoreA:g.scoreB,opp=won?g.scoreB:g.scoreA;if(g.stage==='Regular Season'){rows[m].w+=won?1:0;rows[m].l+=won?0:1;rows[m].pf+=pts;rows[m].pa+=opp}else{rows[m].postW+=won?1:0;rows[m].postL+=won?0:1}}
    if(g.stage==='Postseason'){if(g.round==='Final'){rows[g.winner].titles++;rows[g.winner].finals++;rows[g.loser].finals++;rows[g.winner].best=Math.min(rows[g.winner].best,1);rows[g.loser].best=Math.min(rows[g.loser].best,2)}else if(g.round==='3rd Place'){rows[g.winner].best=Math.min(rows[g.winner].best,3);rows[g.loser].best=Math.min(rows[g.loser].best,4)}else if(g.round==='5th Place'){rows[g.winner].best=Math.min(rows[g.winner].best,5);rows[g.loser].best=Math.min(rows[g.loser].best,6)}else if(g.round==='7th Place'){rows[g.winner].best=Math.min(rows[g.winner].best,7);rows[g.loser].best=Math.min(rows[g.loser].best,8)}else if(/9th Place|Toilet/i.test(g.round)){rows[g.winner].best=Math.min(rows[g.winner].best,9);rows[g.loser].best=Math.min(rows[g.loser].best,10);rows[g.loser].toilets++}}
  }
  return Object.values(rows).map(r=>({...r,seasons:r.seasons.size,pct:r.w/(r.w+r.l||1)}));
}
function seasonArchiveStats(year){
  const games=archiveGames().filter(g=>g.year===year),reg=games.filter(g=>g.stage==='Regular Season'&&scoredGame(g)),post=games.filter(g=>g.stage==='Postseason'&&scoredGame(g)),m={};
  for(const g of reg){for(const who of [g.managerA,g.managerB])m[who]??={manager:who,w:0,l:0,pf:0,pa:0};for(const who of [g.managerA,g.managerB]){const won=g.winner===who,pts=won?g.scoreA:g.scoreB,opp=won?g.scoreB:g.scoreA;m[who].w+=won?1:0;m[who].l+=won?0:1;m[who].pf+=pts;m[who].pa+=opp}}
  const standings=Object.values(m).sort((a,b)=>b.w-a.w||b.pf-a.pf);const high=reg.length?[...reg].sort((a,b)=>Math.max(b.scoreA,b.scoreB)-Math.max(a.scoreA,a.scoreB))[0]:null,low=reg.length?[...reg].sort((a,b)=>Math.min(a.scoreA,a.scoreB)-Math.min(b.scoreA,b.scoreB))[0]:null,big=reg.length?[...reg].sort((a,b)=>Math.abs(b.scoreA-b.scoreB)-Math.abs(a.scoreA-a.scoreB))[0]:null,close=reg.length?[...reg].sort((a,b)=>Math.abs(a.scoreA-a.scoreB)-Math.abs(b.scoreA-b.scoreB))[0]:null,combined=reg.length?[...reg].sort((a,b)=>(b.scoreA+b.scoreB)-(a.scoreA+a.scoreB))[0]:null;
  return {games,reg,post,standings,high,low,big,close,combined};
}
function gameReceipt(g){return g&&scoredGame(g)?`${e(g.winner)} ${g.scoreA.toFixed(2)}–${g.scoreB.toFixed(2)} ${e(g.loser)}`:'—'}

function activityCard(x){
  const type=String(x?.type||'MOVE').toUpperCase(),manager=x?.manager||x?.team||'League move',team=x?.team&&x.team!==manager?x.team:'',add=x?.add||'',drop=x?.drop||'',faab=x?.faab,time=x?.time||x?.date||'';
  const kind=/trade/.test(type.toLowerCase())?'trade':/waiver|claim/.test(type.toLowerCase())?'waiver':/drop/.test(type.toLowerCase())?'drop':'add';
  const fallback=String(x?.description||'Completed transaction').replace(/[\uE000-\uF8FF]/g,'').replace(/\s+/g,' ').trim();
  const players=[add?`<div class="activity-player activity-player-add"><span>ADD</span><strong>${e(add)}</strong></div>`:'',drop?`<div class="activity-player activity-player-drop"><span>DROP</span><strong>${e(drop)}</strong></div>`:''].join('');
  const detail=players||`<p class="activity-description">${e(fallback)}</p>`;
  const spend=faab!=null&&Number.isFinite(Number(faab))?`<span class="activity-faab">$${e(faab)} FAAB</span>`:'';
  const mark=kind==='trade'?'↔':kind==='drop'?'−':'+';
  return `<article class="activity-card activity-card-${kind}"><div class="activity-mark" aria-hidden="true">${mark}</div><div class="activity-main"><div class="activity-owner"><span class="activity-type">${e(type)}</span><strong>${e(manager)}</strong>${team?`<small>${e(team)}</small>`:''}</div><div class="activity-players">${detail}</div></div><div class="activity-meta">${spend}${time?`<time>${e(time)}</time>`:''}</div></article>`;
}
function activityTape(list,emptyCopy){return Array.isArray(list)&&list.length?list.map(activityCard).join(''):`<div class="empty-state"><b>No 2026 transactions yet.</b><br>${e(emptyCopy)}</div>`}

function transactions(){
  let rows=(Y.transactionLeaderboard||[]).map(r=>`<tr><td><b>${e(r[0])}</b></td><td>${e(r[1]??0)}</td><td>${e(r[2]??0)}</td><td>${e(r[3]??0)}</td><td class="move-current"><b>${e(r[4]??0)}</b></td><td class="move-total"><b>${e(r[5]??((Number(r[1])||0)+(Number(r[2])||0)+(Number(r[3])||0)+(Number(r[4])||0)))}</b></td></tr>`).join('');
  const tx=Y.waiverWire?.recentTransactions||[],tape=activityTape(tx,'The live tape is ready; completed adds, drops, claims and trades will appear here when the season starts.');
  return hero('Moves & Trades','Some managers build through the draft. Owen rebuilds the plane while it is in the air.')+sec('2026 activity tape',`<div class="activity-feed">${tape}</div><div style="margin-top:18px"><a class="button primary" href="waiver-wire.html">Open Waiver Wire →</a></div>`,'','LIVE SEASON')+sec('Career move leaderboard',`<div class="table-wrap move-leaderboard-wrap" tabindex="0"><table class="move-leaderboard"><thead><tr><th>Manager</th><th>2023</th><th>2024</th><th>2025</th><th class="move-current">2026</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table></div>`,'2026 updates automatically from the cumulative Yahoo JSON uploads; duplicate sightings of the same transaction are counted once.','THE CHURN')
}
function waiverAvailableSections(players=[]){
 const config=[['QB','Quarterbacks',15],['RB','Running Backs',25],['WR','Wide Receivers',25],['TE','Tight Ends',15],['K','Kickers',10],['DEF','Defenses',10]];
 const pool=Array.isArray(players)?players:[],week=Number(Y.week)||1,model=window.MEFFL_WAIVER_MODEL;
 if(!pool.length)return `<div class="table-wrap" tabindex="0"><table><tbody><tr><td><div class="empty-state"><b>Yahoo connect pending.</b><br>Available players will populate here when live league data is connected.</div></td></tr></tbody></table></div>`;
 const nav=config.map(([pos,label])=>{const count=pool.filter(p=>String(p.position||p.pos||'').toUpperCase()===pos).length;return `<a href="#waiver-${pos.toLowerCase()}" class="waiver-position-pill"><b>${e(pos)}</b><span>${count}</span></a>`}).join('');
 const groups=config.map(([pos,label,target])=>{
   const list=pool.filter(p=>String(p.position||p.pos||'').toUpperCase()===pos).slice(0,target);
   const rows=list.length?list.map((p,i)=>{
     const m=model?.metrics?model.metrics(p,week,i+1,list.length):{recent:week===1?'—':(p.recent??'—'),projected:p.projected??'—',faab:p.faabSuggestion||'—'};
     return `<tr><td><b>${e(p.name)}</b></td><td>${e(p.nflTeam||p.nfl||'')}</td><td><span class="waiver-pos-tag">${e(pos)}</span></td><td>${e(m.recent)}</td><td class="waiver-projected"><b>${e(m.projected)}</b></td><td class="waiver-faab"><b>${e(m.faab)}</b></td></tr>`;
   }).join(''):`<tr><td colspan="6"><div class="empty-state">No ${e(label.toLowerCase())} captured.</div></td></tr>`;
   return `<section class="waiver-position-card" id="waiver-${pos.toLowerCase()}"><div class="waiver-position-head"><div><p class="eyebrow dark">${e(pos)}</p><h3>${e(label)}</h3></div><span class="waiver-position-count">${list.length} listed</span></div><div class="table-wrap waiver-position-table-wrap" tabindex="0"><table class="waiver-position-table"><thead><tr><th>Player</th><th>Team</th><th>Pos</th><th>Recent</th><th>Projected</th><th>Suggested FAAB</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
 }).join('');
 return `<div class="waiver-model-note"><b>Week ${week} model:</b> Recent = previous week's actual points; Projected = MEFFL half-PPR forecast; Suggested FAAB = $100-budget recommendation using projection, positional scarcity, pool depth and availability risk.</div><nav class="waiver-position-nav" aria-label="Available player positions">${nav}</nav><div class="waiver-position-stack">${groups}</div>`;
}
