function simRows(){return [...(E.simulate?E.simulate():[])].sort((a,b)=>b.playoff-a.playoff)}
function barsModel(field,red=false){return simRows().map(x=>`<div class="odds-row"><strong>${e(x.team)}<span class="table-sub">${e(x.manager)}</span></strong><div class="bar${red?' red':''}"><span style="width:${Math.min(100,x[field])}%"></span></div><b>${x[field]}%</b></div>`).join('')}
