function records(){
  const book=E.recordWatch?E.recordWatch():(Y.recordBook||[]).map(r=>({record:r[0],holder:r[1],number:r[2],receipt:r[3]}));let rows=book.map(r=>`<tr><td>${e(r.record)}</td><td>${e(r.holder)}</td><td><b>${e(r.number)}</b></td><td>${e(r.receipt)}</td></tr>`).join('');
  const reg=archiveGames().filter(g=>g.stage==='Regular Season'&&scoredGame(g));
  const hi=[...reg].sort((a,b)=>Math.max(b.scoreA,b.scoreB)-Math.max(a.scoreA,a.scoreB))[0],lo=[...reg].sort((a,b)=>Math.min(a.scoreA,a.scoreB)-Math.min(b.scoreA,b.scoreB))[0],big=[...reg].sort((a,b)=>Math.abs(b.scoreA-b.scoreB)-Math.abs(a.scoreA-a.scoreB))[0],close=[...reg].sort((a,b)=>Math.abs(a.scoreA-a.scoreB)-Math.abs(b.scoreA-b.scoreB))[0],comb=[...reg].sort((a,b)=>(b.scoreA+b.scoreB)-(a.scoreA+a.scoreB))[0];
  const single=(g,which)=>{if(!g)return '—';if(which==='high')return `${g.winner} — ${g.scoreA.toFixed(2)} (${g.year} W${g.week})`;if(which==='low')return `${g.loser} — ${g.scoreB.toFixed(2)} (${g.year} W${g.week})`;return gameReceipt(g)};
  const career=archiveCareerRows().sort((a,b)=>b.w-a.w||b.pf-a.pf).map((r,i)=>`<tr><td>${i+1}</td><td><b>${e(r.manager)}</b></td><td>${r.seasons}</td><td>${r.w}-${r.l}</td><td>${(r.pct*100).toFixed(1)}%</td><td>${r.pf.toFixed(2)}</td><td>${r.pa.toFixed(2)}</td><td>${r.postW}-${r.postL}</td><td>${r.titles}</td><td>${r.finals}</td><td>${r.toilets}</td></tr>`).join('');
  const streaks={};for(const m of archiveManagers()){const gs=reg.filter(g=>g.managerA===m||g.managerB===m).sort((a,b)=>gameOrder(a)-gameOrder(b));let cw=0,cl=0,mw=0,ml=0;for(const g of gs){if(g.winner===m){cw++;cl=0;mw=Math.max(mw,cw)}else{cl++;cw=0;ml=Math.max(ml,cl)}}streaks[m]={mw,ml}}
  const winSt=Object.entries(streaks).sort((a,b)=>b[1].mw-a[1].mw)[0],lossSt=Object.entries(streaks).sort((a,b)=>b[1].ml-a[1].ml)[0];
  return hero('Record Book','The numbers nobody is allowed to forget.')+sec('League records',`<div class="table-wrap" tabindex="0"><table><thead><tr><th>Record</th><th>Holder</th><th>Number</th><th>Receipt</th></tr></thead><tbody>${rows}</tbody></table></div>`)+sec('Historical scoring vault',`<div class="grid3">${card('Highest regular-season score',single(hi,'high'),'CEILING')}${card('Lowest regular-season score',single(lo,'low'),'FLOOR')}${card('Biggest blowout',`${gameReceipt(big)}<br><span class="small">Margin ${Math.abs(big.scoreA-big.scoreB).toFixed(2)}</span>`,'MERCY RULE')}${card('Closest finish',`${gameReceipt(close)}<br><span class="small">Margin ${Math.abs(close.scoreA-close.scoreB).toFixed(2)}</span>`,'INCHES')}${card('Highest combined score',`${gameReceipt(comb)}<br><span class="small">Combined ${(comb.scoreA+comb.scoreB).toFixed(2)}</span>`,'SHOOTOUT')}${card('Longest streaks',`${e(winSt?.[0])} W${winSt?.[1].mw||0}<br>${e(lossSt?.[0])} L${lossSt?.[1].ml||0}`,'RUNS')}</div>`,'','THE VAULT')+sec('Career standings',`<div class="table-wrap" tabindex="0"><table><thead><tr><th>#</th><th>Manager</th><th>Seasons</th><th>Record</th><th>Win %</th><th>PF</th><th>PA</th><th>Postseason</th><th>Titles</th><th>Finals</th><th>Toilets</th></tr></thead><tbody>${career}</tbody></table></div>`,'','FULL LEDGER')+sec('League ledger',E.renderLeaderboards?E.renderLeaderboards():'','','HISTORICAL LEADERBOARDS')
}
