  const scoreGrade=g=>({'A+':7,'A':6,'A-':5,'B+':4.5,'B':4,'B-':3.5,'C+':3,'C':2.5,'C-':2,'D+':1.5,'D':1,'D-':.5,'F':0}[g]??-1);
