function schedule(){
  const sched=E.schedule2026?E.schedule2026():{}, teams=Y.teams||[], rank=Object.fromEntries(HOME_DRAFT_BOARD.map(t=>[t.team,Number(t.rank)||99])), mgr=t=>E.managerByTeam?E.managerByTeam(t):t;
  const games=[];for(let w=1;w<=14;w++)for(const [a,b] of (sched[String(w)]||[]))games.push({w,a,b,ma:mgr(a),mb:mgr(b)});
  const key=(a,b)=>[a,b].sort().join('|'), finalTags={}; finalTags[key('Tommy','Christopher')]='2024 FINAL REMATCH'; finalTags[key('Tommy','Matt F.')]='2025 FINAL REMATCH';
  const pairWeeks={};for(const g of games)(pairWeeks[key(g.ma,g.mb)]??=[]).push(g.w);
  const reg=(ma,mb)=>{const z=E.series?E.series(ma,mb):{regW:0,regL:0};return {w:z.regW||0,l:z.regL||0,total:(z.regW||0)+(z.regL||0)}};
  const tags=g=>{const z=[],k=key(g.ma,g.mb),r=reg(g.ma,g.mb);if(finalTags[k])z.push(finalTags[k]);if((rank[g.a]||99)<=4&&(rank[g.b]||99)<=4)z.push('TOP-4 CLASH');if(r.total>=5&&Math.abs(r.w-r.l)<=1)z.push('RIVALRY');if((pairWeeks[k]||[]).length>1&&g.w>Math.min(...pairWeeks[k]))z.push('SEASON REMATCH');return z};
  const roads=teams.map(t=>{const rs=[];for(let w=1;w<=14;w++){const g=(sched[String(w)]||[]).find(x=>x.includes(t.team));if(g){const o=g[0]===t.team?g[1]:g[0];rs.push(rank[o]||10)}}return {...t,avg:rs.reduce((a,b)=>a+b,0)/(rs.length||1)}}).sort((a,b)=>a.avg-b.avg);
  const uniq=[...new Map(games.map(g=>[key(g.ma,g.mb),g])).values()];
  const familiar=[...uniq].sort((a,b)=>reg(b.ma,b.mb).total-reg(a.ma,a.mb).total)[0];
  const wk1=[...games.filter(g=>g.w===1)].sort((a,b)=>(rank[a.a]+rank[a.b])-(rank[b.a]+rank[b.b]))[0];
  const closest=[...uniq].filter(g=>reg(g.ma,g.mb).total>=4).sort((a,b)=>Math.abs(reg(a.ma,a.mb).w-reg(a.ma,a.mb).l)-Math.abs(reg(b.ma,b.mb).w-reg(b.ma,b.mb).l)||reg(b.ma,b.mb).total-reg(a.ma,a.mb).total)[0];
  const marqueeScore=g=>tags(g).reduce((s,t)=>s+(t.includes('FINAL REMATCH')?100:t==='TOP-4 CLASH'?35:t==='RIVALRY'?25:10),0);
  const marqueeId=g=>`${g.w}|${key(g.ma,g.mb)}`;
  const marqueeGames=[...games].filter(g=>tags(g).length).sort((a,b)=>marqueeScore(b)-marqueeScore(a)||a.w-b.w).slice(0,16);
  const marqueeChosen=new Set(marqueeGames.map(marqueeId)), marqueeCounts=Object.fromEntries(teams.map(t=>[t.manager,0])), extraMarqueeTags={};
  const bumpMarquee=g=>{marqueeCounts[g.ma]=(marqueeCounts[g.ma]||0)+1;marqueeCounts[g.mb]=(marqueeCounts[g.mb]||0)+1};
  marqueeGames.forEach(bumpMarquee);
  while(teams.some(t=>(marqueeCounts[t.manager]||0)<2)){
    const candidates=games.filter(g=>!marqueeChosen.has(marqueeId(g))&&((marqueeCounts[g.ma]||0)<2||(marqueeCounts[g.mb]||0)<2));
    if(!candidates.length)break;
    candidates.sort((a,b)=>{
      const ra=reg(a.ma,a.mb),rb=reg(b.ma,b.mb),na=((marqueeCounts[a.ma]||0)<2?1:0)+((marqueeCounts[a.mb]||0)<2?1:0),nb=((marqueeCounts[b.ma]||0)<2?1:0)+((marqueeCounts[b.mb]||0)<2?1:0);
      const sa=na*100+marqueeScore(a)*2+ra.total*3-Math.abs(ra.w-ra.l)*2,sb=nb*100+marqueeScore(b)*2+rb.total*3-Math.abs(rb.w-rb.l)*2;
      return sb-sa||a.w-b.w||(rank[a.a]+rank[a.b])-(rank[b.a]+rank[b.b]);
    });
    const g=candidates[0],r=reg(g.ma,g.mb),id=marqueeId(g);marqueeGames.push(g);marqueeChosen.add(id);bumpMarquee(g);
    if(!tags(g).length)extraMarqueeTags[id]=r.total>=6&&Math.abs(r.w-r.l)<=1?'EVEN SERIES':r.total>=6?'HISTORY':'FEATURED MATCHUP';
  }
  marqueeGames.sort((a,b)=>a.w-b.w||marqueeScore(b)-marqueeScore(a)||a.a.localeCompare(b.a));
  const marquee=marqueeGames.map(g=>{const r=reg(g.ma,g.mb),displayTags=[...tags(g),...(extraMarqueeTags[marqueeId(g)]?[extraMarqueeTags[marqueeId(g)]]:[])];return `<a class="marquee-game" href="week.html?week=${g.w}"><div><span>WEEK ${g.w}</span><b>${e(g.a)} vs ${e(g.b)}</b><small>${e(g.ma)} ${r.w}-${r.l} ${e(g.mb)} in 2023–25 regular-season meetings</small></div><div>${displayTags.map(x=>`<em>${e(x)}</em>`).join('')}</div></a>`}).join('');
  const teamCards=teams.map(t=>{const lines=[];for(let w=1;w<=14;w++){const g=(sched[String(w)]||[]).find(x=>x.includes(t.team));if(!g)continue;const o=g[0]===t.team?g[1]:g[0],om=mgr(o),r=reg(t.manager,om),h=E.matchupHistory?E.matchupHistory(t.team,o):null,tg=tags({w,a:t.team,b:o,ma:t.manager,mb:om});lines.push(`<a class="schedule-line${tg.length?' big':''}" href="week.html?week=${w}"><span class="schedule-week">W${w}</span><span class="schedule-opponent">${E.badge?E.badge(o,'xs'):''}<b>${e(o)}</b><small>${e(om)} · REG H2H ${e(t.manager)} ${r.w}-${r.l}</small><small class="schedule-last">${h&&h.total?`Last: ${e(h.previous)}`:'First meeting in the archive'}</small></span><span class="schedule-tags">${tg.map(x=>`<em>${e(x)}</em>`).join('')}</span></a>`)}return `<article class="schedule-team-card"><div class="schedule-team-head"><div><p class="eyebrow dark">PRESEASON #${e(rank[t.team]||t.rank)}</p><h3>${e(t.team)}</h3><p>${e(t.manager)} · Avg opponent preseason rank ${roads.find(x=>x.team===t.team).avg.toFixed(2)}</p></div></div>${lines.join('')}</article>`}).join('');
  const weekly=Array.from({length:14},(_,i)=>i+1).map(w=>`<article class="schedule-week-card"><div class="schedule-week-head"><span>WEEK ${w}</span><a href="week.html?week=${w}">Open week →</a></div>${(sched[String(w)]||[]).map(([a,b])=>{const ma=mgr(a),mb=mgr(b),r=reg(ma,mb),tg=tags({w,a,b,ma,mb});return `<div class="schedule-master-game"><div><b>${e(a)}</b><span>vs</span><b>${e(b)}</b></div><small>${e(ma)} ${r.w}-${r.l} ${e(mb)}</small><div>${tg.map(x=>`<em>${e(x)}</em>`).join('')}</div></div>`}).join('')}</article>`).join('');
  return hero('2026 Schedule','Fourteen regular-season weeks with the full 2023–2025 receipts attached.')+`<section class="section schedule-notables-section"><div class="shell"><div class="section-head"><div><p class="eyebrow dark">SCHEDULE NOTABLES</p><h2>What jumps off the page</h2></div></div><div class="grid4 schedule-notables">${card('Hardest road',`${e(roads[0].team)}<br><span class="small">${e(roads[0].manager)} · avg opponent rank ${roads[0].avg.toFixed(2)}</span>`,'SCHEDULE STRENGTH')}${card('Softest road',`${e(roads[roads.length-1].team)}<br><span class="small">${e(roads[roads.length-1].manager)} · avg opponent rank ${roads[roads.length-1].avg.toFixed(2)}</span>`,'SCHEDULE STRENGTH')}${card('Most familiar matchup',`${e(familiar.a)} vs ${e(familiar.b)}<br><span class="small">${e(familiar.ma)} ${reg(familiar.ma,familiar.mb).w}-${reg(familiar.ma,familiar.mb).l} ${e(familiar.mb)} · ${reg(familiar.ma,familiar.mb).total} prior regular-season meetings</span>`,'HISTORY')}${card('Week 1 heavyweight',`${e(wk1.a)} vs ${e(wk1.b)}<br><span class="small">Preseason #${rank[wk1.a]} vs #${rank[wk1.b]}</span>`,'OPENING WEEK')}</div>${closest?`<div class="notice"><b>Closest established series:</b> ${e(closest.ma)} ${reg(closest.ma,closest.mb).w}-${reg(closest.ma,closest.mb).l} ${e(closest.mb)} across ${reg(closest.ma,closest.mb).total} regular-season meetings.</div>`:''}</div></section>`+sec('Marquee dates',`<div class="marquee-list">${marquee||'<div class="empty-state">No tagged marquee games.</div>'}</div>`,'','CIRCLE THESE')+`<section class="section alt"><div class="shell"><div class="section-head"><div><p class="eyebrow dark">TEAM-BY-TEAM</p><h2>Every road to Week 14</h2></div></div><div class="schedule-team-grid">${teamCards}</div></div></section>`+sec('Full 14-week slate',`<div class="schedule-week-grid">${weekly}</div>`,'','MASTER SCHEDULE')
}
const routes={home,franchises,franchise,transactions,waivers,power,odds,records,weeks,week,history,warroom,h2h,schedule,seasonArchive,trophies};
const currentPage=document.body.dataset.page;
document.body.innerHTML=nav()+(routes[currentPage]||home)()+foot();
if(currentPage==='waivers'){refreshWaivers();const cfg=window.MEFFL_API||{};if(cfg.waiverEndpoint)setInterval(refreshWaivers,Math.max(60,cfg.refreshSeconds||120)*1000)}
